import base64, re
png_text = ""
b = base64.b64decode(png_text)
def rot13(bs):
    out=bytearray()
    for c in bs:
        if 65<=c<=90: out.append(65+((c-65+13)%26))
        elif 97<=c<=122: out.append(97+((c-97+13)%26))
        else: out.append(c)
    return bytes(out)
B64CHARS = set(b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=\n')
for k in range(256):
    r = rot13(bytes(c ^ k for c in b))
    if all(c in B64CHARS for c in r):
        print("KEY", k)
        print(r)
        b2 = base64.b64decode(r)
        print("b64 len:", len(b2))
        # stage 4 known plaintext
        marker = b"SECRET_DATA:"
        ks = bytes(b2[i] ^ marker[i] for i in range(len(marker)))
        for L in range(1,5):
            pat = ks[:L]
            if all(ks[i] == pat[i % L] for i in range(len(marker))):
                print("key len", L, pat.hex())
                pt = bytes(b2[i] ^ pat[i % L] for i in range(len(b2)))
                print(pt.decode())
