{"command": "cat > /app/canonicalize.py << 'EOF'
#!/usr/bin/env python3
"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration to
/app/output.txt.
"""
import re
import sys

INPUT_PATH = sys.argv[1] if len(sys.argv) > 1 else "/app/input.txt"
OUTPUT_PATH = sys.argv[2] if len(sys.argv) > 2 else "/app/output.txt"

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}

VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace valid {variable} patterns with {var} for matching."""
    return VAR_RE.sub("{var}", path)


def parse_input(text):
    """Split the raw input into the three sections separated by empty lines."""
    sections = [[] for _ in range(3)]
    current = []
    section_idx = 0
    for raw in text.split("\n"):
        if raw.strip() == "":
            current.append("")
            continue
        current.append(raw)
    # Rebuild: sections are blocks separated by one or more empty lines.
    blocks = []
    buf = []
    for line in text.split("\n"):
        if line.strip() == "":
            if buf:
                blocks.append(buf)
                buf = []
        else:
            buf.append(line)
    if buf:
        blocks.append(buf)
    for i, block in enumerate(blocks[:3]):
        sections[i] = block
    return sections


def parse_endpoints(lines):
    """Parse ENDPOINTS with hard cutoff on the first malformed line."""
    endpoints = []
    for line in lines:
        fields = line.split()
        if len(fields) != 4:
            break
        path, method, role, permission = fields
        method = method.upper()
        permission = permission.upper()
        if path.strip() == "" or role.strip() == "":
            break
        if method not in VALID_METHODS:
            break
        if permission not in VALID_PERMISSIONS:
            break
        endpoints.append((path, method, role, permission))
    return endpoints


def parse_base_exclude(lines):
    base = None
    exclude = []
    for line in lines:
        fields = line.split()
        if not fields:
            continue
        if fields[0] == "base":
            if len(fields) >= 2:
                base = fields[1]
        elif fields[0] == "exclude":
            exclude = fields[1:]
    return base, exclude


def parse_plan(lines):
    """Parse PLAN with hard cutoff on the first malformed line."""
    plan = []
    for line in lines:
        fields = line.split()
        if len(fields) != 2:
            break
        path, method = fields
        method = method.upper()
        if path.strip() == "" or method not in VALID_METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open(INPUT_PATH, "r") as f:
        text = f.read()

    sections = parse_input(text)
    endpoints = parse_endpoints(sections[0])
    base, exclude = parse_base_exclude(sections[1])
    plan = parse_plan(sections[2])
    excluded = set(exclude)

    # Normalized-path bookkeeping.
    norm_of = {}
    for path in {e[0] for e in endpoints} | {p for p, _ in plan}:
        norm_of[path] = normalize_path(path)

    # First-encountered original path per normalized path (input order).
    first_path_for_norm = {}
    for path, _, _, _ in endpoints:
        n = norm_of[path]
        if n not in first_path_for_norm:
            first_path_for_norm[n] = path

    def is_eligible(ep):
        path, _, role, _ = ep
        if base is not None and not path.startswith(base):
            return False
        if role in excluded:
            return False
        return True

    # Rule 3: dedupe by (normalized path, method, role) keeping first.
    seen = set()
    deduped = []
    for ep in endpoints:
        n = norm_of[ep[0]]
        key = (n, ep[1], ep[2])
        if key in seen:
            continue
        seen.add(key)
        deduped.append(ep)

    eligible = [ep for ep in deduped if is_eligible(ep)]

    # Determine which normalized paths are needed (PLAN + parents).
    plan_norms = set()
    for path, _ in plan:
        plan_norms.add(norm_of[path])

    all_norms = sorted({norm_of[ep[0]] for ep in deduped})

    def has_eligible(norm):
        return any(norm_of[ep[0]] == norm for ep in eligible)

    def has_deduped(norm):
        return any(norm_of[ep[0]] == norm for ep in deduped)

    needed = set()
    if plan:
        needed.update(plan_norms)
        # Parent path resolution: a normalized path p is a parent of endpoint
        # normalized path e if p is a proper prefix of e.
        for e in plan_norms:
            for p in all_norms:
                if p != e and e.startswith(p) and has_eligible(p):
                    needed.add(p)
    else:
        for n in all_norms:
            if has_eligible(n):
                needed.add(n)

    # Special case: parent path whose only endpoints are for excluded roles,
    # included only if it is the sole provider for that parent path and the
    # parent path is needed for inheritance.
    needed_parents = set()
    if plan:
        for e in plan_norms:
            for p in all_norms:
                if p != e and e.startswith(p):
                    needed_parents.add(p)

    selected = []
    for ep in deduped:
        n = norm_of[ep[0]]
        if n not in needed:
            continue
        if is_eligible(ep):
            selected.append(ep)
        elif plan and n in needed_parents and not has_eligible(n):
            # Only endpoints for excluded roles at this path, and this path is
            # needed for inheritance.
            if not any(norm_of[e[0]] == n and is_eligible(e) for e in deduped):
                selected.append(ep)

    # Rule 4: ordering.
    def seg_count(path):
        return len([s for s in path.split("/") if s])

    def sort_key(ep):
        path, method, role, permission = ep
        return (-seg_count(path), method, role, 0 if permission == "ALLOW" else 1)

    selected.sort(key=sort_key)

    # Rule 7: uniqueness by (original path, method, role).
    out_seen = set()
    out_lines = []
    for ep in selected:
        key = (ep[0], ep[1], ep[2])
        if key in out_seen:
            continue
        out_seen.add(key)
        out_lines.append(" ".join(ep))

    output = "\n".join(out_lines) + "\n" if out_lines else "\n"
    with open(OUTPUT_PATH, "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
