        if len(fields) != 2:
            break
        path, method = fields
        if path.strip() == '':
            break
        method = method.upper()
        if method not in METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open('/app/input.txt', 'r') as f:
        text = f.read()

    ep_lines, be_lines, plan_lines = split_sections(text)

    endpoints = parse_endpoints(ep_lines)
    base, excluded = parse_base_exclude(be_lines)
    plan = parse_plan(plan_lines)

    # Base prefix filter (exact prefix match on the original path)
    if base is not None:
        eligible = [e for e in endpoints if e['path'].startswith(base)]
    else:
        eligible = list(endpoints)

    # Group eligible endpoints by normalized path
    paths_by_norm = {}
    for e in eligible:
        paths_by_norm.setdefault(e['norm_path'], []).append(e)
    all_norm_paths = set(paths_by_norm.keys())

    # Determine which normalized paths are "requested".
    # An empty PLAN means all eligible endpoints are requested.
    if plan:
        requested = set(normalize_path(p) for p, _ in plan)
    else:
        requested = set(all_norm_paths)

    # Parent path resolution: include parent normalized paths of requested
    # paths. A path is a parent if its normalized form is a proper prefix of
    # the endpoint's normalized form and it has at least one eligible
    # endpoint (after base/exclude filtering).
    included_paths = set(requested)
    for rp in requested:
        for candidate in all_norm_paths:
            if candidate != rp and rp.startswith(candidate):
                included_paths.add(candidate)

    # Build output endpoints.
    # Excluded-role endpoints are filtered out, EXCEPT when the path is a
    # proper parent of a requested path (needed for inheritance) and ALL
    # endpoints for that parent path are for excluded roles (they are then
    # the only endpoints for that parent path, so they are included).
    # When PLAN is empty, requested == all eligible paths, so no path is a
    # proper parent of a requested path and excluded roles are always
    # filtered out.
    output = []
    for norm_path in included_paths:
        eps = paths_by_norm.get(norm_path, [])
        inheritance_case = (norm_path not in requested) and \
            all(e['role'] in excluded for e in eps)
        for e in eps:
            if e['role'] in excluded and not inheritance_case:
                continue
            output.append(e)

    # Deduplicate on (normalized path, method, role); keep the first
    # encountered endpoint (by ENDPOINTS input order, before cutoff).
    # The first endpoint also carries the original variable names used in
    # the output.
    seen = set()
    deduped = []
    for e in sorted(output, key=lambda e: e['index']):
        key = (e['norm_path'], e['method'], e['role'])
        if key in seen:
            continue
        seen.add(key)
        deduped.append(e)

    # Path specificity ordering:
    #   1. path length in segments (longer first)
    #   2. method (alphabetical)
    #   3. role (lexicographic, case-sensitive)
    #   4. permission (ALLOW before DENY)
    def sort_key(e):
        n_segments = len([s for s in e['norm_path'].split('/') if s])
        return (-n_segments, e['method'], e['role'],
                0 if e['permission'] == 'ALLOW' else 1)

    deduped.sort(key=sort_key)

    if deduped:
        out = ''.join('{} {} {} {}\n'.format(
            e['path'], e['method'], e['role'], e['permission'])
            for e in deduped)
    else:
        out = '\n'

    with open('/app/output.txt', 'w') as f:
        f.write(out)


if __name__ == '__main__':
    main()
"}

