        if line.strip() == "":
            sections.append(current)
            current = []
        else:
            current.append(line)
    sections.append(current)
    # Drop trailing empty sections (e.g. trailing newlines)
    while sections and not sections[-1]:
        sections.pop()
    return sections


def looks_like_base_exclude(sec):
