    # ---- Output path: first encountered original path (by input order)
    #      per normalized path among the endpoints in the output ----
    first_original = {}
    for ep in deduped:
        first_original.setdefault(ep["npath"], ep["path"])

    # ---- Order: segments desc, method alpha, role lexicographic,
    #      permission (ALLOW before DENY) ----
    def sort_key(ep):
        return (
            -count_segments(ep["path"]),
            ep["method"],
            ep["role"],
