import base64, codecs
text = ''
raw = base64.b64decode(text)
marker = b'SECRET_DATA:'
for k in range(256):
    x = bytes(b ^ k for b in raw)
    for cand, name in ((x,'s'), (codecs.decode(x.decode('latin1'),'rot13').encode('latin1'),'r')):
        try:
            ct = base64.b64decode(cand)
        except:
            continue
        if len(ct) < 12: continue
        # derive key from marker for lengths 1-4
        for L in range(1,5):
            key = bytes(ct[i] ^ marker[i] for i in range(L))
            if all(key[i % L] == key[i//L % L] for i in range(L)):
                # check full
                pt = bytes(c ^ key[i%L] for i,c in enumerate(ct))
                if pt.startswith(marker):
                    print('key',k,'name',name,'L',L,'keyhex',key.hex())
                    print(pt[:200])
""}

