{"path": "/app/canonicalize.py", "content": "#!/usr/bin/env python3
"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt, writes canonical permission configuration to /app/output.txt.
"""
import re

VALID_METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
VALID_PERMS = {'ALLOW', 'DENY'}
VAR_RE = re.compile(r'\{([A-Za-z0-9_-]+)\}')


def normalize_path(path):
    """Replace {variable_name} patterns with {var} for matching."""
    return VAR_RE.sub('{var}', path)


def segment_count(path):
    return len([s for s in path.split('/') if s])


def read_sections():
    with open('/app/input.txt') as f:
        text = f.read()
    sections = []
    cur = []
    for line in text.split('\n'):
        if line.strip() == '':
            if cur:
                sections.append(cur)
                cur = []
        else:
            cur.append(line)
    if cur:
        sections.append(cur)
    while len(sections) < 3:
        sections.append([])
    return sections[:3]


def parse_endpoints(lines):
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break  # hard cutoff
        path, method, role, perm = parts
        if not path.strip():
            break
        if method.upper() not in VALID_METHODS:
            break
        if perm.upper() not in VALID_PERMS:
            break
        if not role.strip():
            break
        endpoints.append((path, method.upper(), role, perm.upper()))
    return endpoints


def parse_base_exclude(lines):
    base = None
    exclude = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == 'base' and len(parts) >= 2:
            base = parts[1]
        elif parts[0] == 'exclude':
            exclude.update(parts[1:])
    return base, exclude


def parse_plan(lines):
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break  # hard cutoff
        path, method = parts
        if not path.strip():
            break
        if method.upper() not in VALID_METHODS:
            break
        plan.append((normalize_path(path), method.upper()))
    return plan


def main():
    sec_endpoints, sec_base_exclude, sec_plan = read_sections()

    endpoints = parse_endpoints(sec_endpoints)
    base, exclude = parse_base_exclude(sec_base_exclude)
    plan = parse_plan(sec_plan)

    n = len(endpoints)
    norms = [normalize_path(e[0]) for e in endpoints]

    base_ok = [
        True if base is None else e[0].startswith(base)
        for e in endpoints
    ]
    eligible = [
        base_ok[i] and endpoints[i][2] not in exclude
        for i in range(n)
    ]

    def is_parent(P):
        """P (normalized) is a parent path if it has at least one eligible
        endpoint, or (special case) if it has endpoints only for excluded
        roles and at least one base-matching endpoint."""
        idxs = [i for i in range(n) if norms[i] == P]
        if not idxs:
            return False
        if any(eligible[i] for i in idxs):
            return True
        if all(endpoints[i][2] in exclude for i in idxs) and \
                any(base_ok[i] for i in idxs):
            return True
        return False

    selected = set()
    if not plan:
        # Include all eligible endpoints; excluded roles always filtered out.
        for i in range(n):
            if eligible[i]:
                selected.add(i)
    else:
        # Valid plan entries: those present in ENDPOINTS (before cutoff).
        valid = set()
        for (np, m) in plan:
            if any(norms[i] == np and endpoints[i][1] == m for i in range(n)):
                valid.add((np, m))

        all_norms = set(norms)
        for (np, m) in valid:
            # Endpoints explicitly in PLAN (eligible only).
            for i in range(n):
                if norms[i] == np and endpoints[i][1] == m and eligible[i]:
                    selected.add(i)
            # Parent paths for hierarchical permission inheritance.
            for P in all_norms:
                if P == np or not np.startswith(P):
                    continue
                if is_parent(P):
                    for i in range(n):
                        if norms[i] == P and base_ok[i]:
                            selected.add(i)

    # Deduplicate: first encountered (input order) per (norm path, method, role).
    best = {}
    for i in range(n):
        if i in selected:
            key = (norms[i], endpoints[i][1], endpoints[i][2])
            if key not in best:
                best[key] = i

    # Representative original path per normalized path (first in input order).
    rep = {}
    for i in range(n):
        if norms[i] not in rep:
            rep[norms[i]] = endpoints[i][0]

    rows = []
    for (np, m, role), i in best.items():
        rows.append((rep[np], m, role, endpoints[i][3]))

    rows.sort(key=lambda r: (
        -segment_count(r[0]),
        r[1],
        r[2],
        0 if r[3] == 'ALLOW' else 1,
        r[0],
    ))

    if rows:
        out = '\n'.join('%s %s %s %s' % r for r in rows) + '\n'
    else:
        out = '\n'

    with open('/app/output.txt', 'w') as f:
        f.write(out)


if __name__ == '__main__':
    main()
"}

{"path": "/app/canonicalize.py", "content": "#!/usr/bin/env python3
"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}

VAR_PATTERN = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace all valid {variable} patterns with {var} for matching."""
    return VAR_PATTERN.sub("{var}", path)


def segment_count(path):
    """Count non-empty segments after splitting on '/'."""
    return len([s for s in path.split("/") if s != ""])


def main():
    with open("/app/input.txt", "r") as f:
        content = f.read()

    lines = content.split("\n")
    # Drop a single trailing empty line produced by the final newline
    if lines and lines[-1] == "":
        lines.pop()

    # Split into sections on empty lines
    sections = []
    current = []
    for line in lines:
        if line.strip() == "":
            sections.append(current)
            current = []
        else:
            current.append(line)
    sections.append(current)

    # Section 1: ENDPOINTS, Section 2: BASE/EXCLUDE, Section 3: PLAN
    endpoints_lines = sections[0] if len(sections) > 0 else []
    base_exclude_lines = sections[1] if len(sections) > 1 else []
    plan_lines = sections[2] if len(sections) > 2 else []

    # ---- Parse ENDPOINTS (with hard cutoff) ----
    # Each entry: (original_path, method, role, permission)
    endpoints = []
    for line in endpoints_lines:
        parts = line.split()
        if len(parts) != 4:
            break
        path, method, role, permission = parts
        if path.strip() == "":
            break
        method_u = method.upper()
        if method_u not in VALID_METHODS:
            break
        if permission.upper() not in VALID_PERMISSIONS:
            break
        if role.strip() == "":
            break
        endpoints.append((path, method_u, role, permission.upper()))

    # ---- Parse BASE/EXCLUDE ----
    base = None
    exclude = set()
    for line in base_exclude_lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base":
            if len(parts) >= 2:
                base = parts[1]
        elif parts[0] == "exclude":
            for r in parts[1:]:
                exclude.add(r)

    # ---- Parse PLAN (with hard cutoff) ----
    plan = []
    for line in plan_lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if path.strip() == "":
            break
        method_u = method.upper()
        if method_u not in VALID_METHODS:
            break
        plan.append((path, method_u))

    # ---- Determine eligibility (base / exclude) ----
    def eligible(ep):
        path, method, role, permission = ep
        if base is not None and not path.startswith(base):
            return False
        if role in exclude:
            return False
        return True

    eligible_eps = [ep for ep in endpoints if eligible(ep)]

    # Set of normalized parent paths that have at least one eligible endpoint
    eligible_parent_norms = {normalize_path(ep[0]) for ep in eligible_eps}

    # ---- Determine which endpoints are included ----
    plan_norms = set()
    for p, m in plan:
        plan_norms.add((normalize_path(p), m))

    included = set()  # indices into endpoints

    if len(plan) == 0:
        # All eligible endpoints (excluded roles filtered out, no inheritance exception)
        for i, ep in enumerate(endpoints):
            if eligible(ep):
                included.add(i)
    else:
        # Endpoints whose normalized (path, method) is in PLAN
        for i, (path, method, role, permission) in enumerate(endpoints):
            if (normalize_path(path), method) in plan_norms:
                included.add(i)

        # Parent path resolution: for each planned endpoint, find parent paths
        # (normalized parent is a proper prefix of the normalized planned path)
        # and include all endpoints for such parent paths that are eligible,
        # plus the special inheritance case for excluded-role-only parents.
        planned_norm_paths = set()
        for p, m in plan:
            planned_norm_paths.add(normalize_path(p))

        # All distinct normalized paths present in ENDPOINTS (before cutoff)
        all_norm_paths = set()
        for ep in endpoints:
            all_norm_paths.add(normalize_path(ep[0]))

        needed_parents = set()
        for pp in planned_norm_paths:
            for cand in all_norm_paths:
                if cand == pp:
                    continue
                if pp.startswith(cand):
                    needed_parents.add(cand)

        for cand in needed_parents:
            # Endpoints at this (normalized) parent path
            cand_eps = [
                i for i, ep in enumerate(endpoints)
                if normalize_path(ep[0]) == cand
            ]
            if not cand_eps:
                continue
            cand_eligible = [i for i in cand_eps if i in included or eligible(endpoints[i])]
            # A parent path must have at least one eligible endpoint to count
            if not any(eligible(endpoints[i]) for i in cand_eps):
                # Special case: include only if ALL endpoints for this parent
                # path are for excluded roles (needed for inheritance) and the
                # parent is needed for inheritance (it is, by construction).
                if all(endpoints[i][2] in exclude for i in cand_eps):
                    for i in cand_eps:
                        included.add(i)
                continue
            for i in cand_eps:
                if eligible(endpoints[i]):
                    included.add(i)

    # ---- Deduplication: first (path, method, role) wins, keyed on normalized path ----
    seen = set()
    final = []
    for i in sorted(included):
        path, method, role, permission = endpoints[i]
        key = (normalize_path(path), method, role)
        if key in seen:
            continue
        seen.add(key)
        final.append((path, method, role, permission))

    # ---- Ordering: more specific paths first (more segments), then method,
    #      then role (lexicographic, case-sensitive), then ALLOW before DENY ----
    def sort_key(ep):
        path, method, role, permission = ep
        return (
            -segment_count(path),
            method,
            role,
            0 if permission == "ALLOW" else 1,
        )

    final.sort(key=sort_key)

    # ---- Output ----
    if final:
        out = "\n".join("%s %s %s %s" % ep for ep in final) + "\n"
    else:
        out = "\n"

    with open("/app/output.txt", "w") as f:
        f.write(out)


if __name__ == "__main__":
    main()
"}

{"path": "/app/canonicalize.py", "content": "#!/usr/bin/env python3
"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

INPUT_PATH = "/app/input.txt"
OUTPUT_PATH = "/app/output.txt"

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}
ROLE_RE = re.compile(r"^[A-Za-z0-9_-]+$")
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace all valid {variable} patterns with {var}."""
    return VAR_RE.sub("{var}", path)


def count_segments(path):
    """Count non-empty segments split on '/'."""
    return len([s for s in path.split("/") if s != ""])


def split_sections(text):
    """Split input into sections separated by blank lines."""
    sections = []
    current = []
    for line in text.split("\n"):
        if line.strip() == "":
            if current:
                sections.append(current)
                current = []
            else:
                # Multiple consecutive blank lines: treat as a section of
                # nothing; keep structure simple by not appending empties.
                pass
        else:
            current.append(line)
    if current:
        sections.append(current)
    return sections


def parse_endpoints(lines):
    """Parse ENDPOINTS section with hard cutoff on malformed lines.

    Returns list of endpoint dicts in input order.
    """
    endpoints = []
    for line in lines:
        parts = line.split()
        if len(parts) != 4:
            break  # hard cutoff
        path, method, role, permission = parts
        if path.strip() == "":
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        if permission.upper() not in VALID_PERMISSIONS:
            break
        role = role.strip()
        if role == "":
            break
        if not ROLE_RE.match(role):
            break
        endpoints.append({
            "path": path,
            "norm": normalize_path(path),
            "method": method,
            "role": role,
            "permission": permission.upper(),
        })
    return endpoints


def parse_base_exclude(lines):
    """Parse BASE/EXCLUDE section."""
    base = None
    exclude = set()
    for line in lines:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "base":
            if len(parts) >= 2:
                base = parts[1]
        elif parts[0] == "exclude":
            for r in parts[1:]:
                exclude.add(r)
    return base, exclude


def parse_plan(lines):
    """Parse PLAN section with hard cutoff on malformed lines.

    Returns list of (path, method) tuples in input order.
    """
    plan = []
    for line in lines:
        parts = line.split()
        if len(parts) != 2:
            break
        path, method = parts
        if path.strip() == "":
            break
        method = method.upper()
        if method not in VALID_METHODS:
            break
        plan.append((path, method))
    return plan


def main():
    with open(INPUT_PATH, "r") as f:
        text = f.read()

    sections = split_sections(text)

    endpoints = []
    base = None
    exclude = set()
    plan = []

    if len(sections) >= 1:
        endpoints = parse_endpoints(sections[0])
    if len(sections) >= 2:
        base, exclude = parse_base_exclude(sections[1])
    if len(sections) >= 3:
        plan = parse_plan(sections[2])

    # Eligibility: base prefix match + exclude filtering
    eligible = []
    for ep in endpoints:
        if base is not None and not ep["path"].startswith(base):
            continue
        if ep["role"] in exclude:
            continue
        eligible.append(ep)

    # Determine the set of endpoint indices to include.
    include_idx = set()

    if not plan:
        # PLAN empty: include all eligible endpoints.
        for i, ep in enumerate(endpoints):
            if ep in eligible:
                include_idx.add(i)
        # Also handle parent-path inheritance for all eligible endpoints?
        # With PLAN empty, "all eligible endpoints" already covers parents
        # of eligible endpoints that are themselves eligible. The special
        # case for excluded-role-only parents applies to inheritance needs;
        # with PLAN empty there are no specific PLAN endpoints to inherit
        # from, so excluded roles stay filtered out.
    else:
        # For each PLAN endpoint, include matching endpoints and their
        # parent-path endpoints.
        for p_path, p_method in plan:
            p_norm = normalize_path(p_path)
            # Matching endpoints: same normalized path
            for i, ep in enumerate(endpoints):
                if ep["norm"] == p_norm:
                    if ep in eligible:
                        include_idx.add(i)
                    else:
                        # endpoint exists but is not eligible (base or
                        # excluded role); only include if eligible
                        pass
            # Parent paths: any distinct normalized path that is a prefix
            # of p_norm and has at least one eligible endpoint.
            parent_norms = set()
            for ep in eligible:
                if ep["norm"] != p_norm and p_norm.startswith(ep["norm"]):
                    parent_norms.add(ep["norm"])
            for norm in parent_norms:
                # Include all endpoints for this parent path that are
                # eligible.
                for i, ep in enumerate(endpoints):
                    if ep["norm"] == norm and ep in eligible:
                        include_idx.add(i)
                # Special case: parent path whose only endpoints are for
                # excluded roles (not base-filtered) and is needed for
                # inheritance -> include them.
                all_eps_at_norm = [ep for ep in endpoints if ep["norm"] == norm]
                if all_eps_at_norm:
                    non_excluded = [ep for ep in all_eps_at_norm
                                    if ep["role"] not in exclude]
                    if not non_excluded and all_eps_at_norm:
                        # only excluded-role endpoints exist here
                        for i, ep in enumerate(endpoints):
                            if ep["norm"] == norm:
                                include_idx.add(i)

    # Deduplicate: one endpoint per (normalized path, method, role),
    # first encountered in input order.
    seen = set()
    chosen = []
    for i in sorted(include_idx):
        ep = endpoints[i]
        key = (ep["norm"], ep["method"], ep["role"])
        if key in seen:
            continue
        seen.add(key)
        chosen.append(ep)

    # Preserve original variable names: if multiple endpoints share the
    # same normalized path but different variable names, use the first
    # encountered (by input order) variable name.
    # Build a mapping from normalized path -> original path (first
    # occurrence in endpoints list).
    norm_to_original = {}
    for ep in endpoints:
        if ep["norm"] not in norm_to_original:
            norm_to_original[ep["norm"]] = ep["path"]

    for ep in chosen:
        ep["out_path"] = norm_to_original[ep["norm"]]

    # Ordering:
    # 1. path length in segments (longer first)
    # 2. method alphabetical
    # 3. role lexicographic (case-sensitive)
    # 4. permission ALLOW before DENY
    def sort_key(ep):
        return (
            -count_segments(ep["out_path"]),
            ep["method"],
            ep["role"],
            0 if ep["permission"] == "ALLOW" else 1,
        )

    chosen.sort(key=sort_key)

    # Uniqueness on (original path, method, role)
    final = []
    seen2 = set()
    for ep in chosen:
        key = (ep["out_path"], ep["method"], ep["role"])
        if key in seen2:
            continue
        seen2.add(key)
        final.append(ep)

    if final:
        out_lines = ["{} {} {} {}".format(ep["out_path"], ep["method"],
                                          ep["role"], ep["permission"])
                     for ep in final]
        output = "\n".join(out_lines) + "\n"
    else:
        output = "\n"

    with open(OUTPUT_PATH, "w") as f:
        f.write(output)


if __name__ == "__main__":
    main()
"}

