bash <<'EOF'
set -u
SUS_CMD='(base64[[:space:]]+(-d|--decode)|\beval\b|\bshred\b|\bchmod[[:space:]]+[0-7]*[67][0-7][0-7]\b|\bmkfifo\b|\bnc\b[[:space:]]|\bncat\b|\bnetcat\b|\bsocat\b|\bssh[[:space:]]+-R\b|bash[[:space:]]+-i|sh[[:space:]]+-i|/dev/tcp/|/dev/udp/|attacker|backdoor|malicious)'
SUS_NET='(^|[[:space:]])(curl|wget)([[:space:]]|$)'
SUS_TMP='(/tmp/|/var/tmp/|/dev/shm/)'
SUS_DOTFILE='(^|[^[:alnum:]_.])\.[^[:space:]/]+([^[:space:]]|$)'
SUS_SENS='(/etc/crontab|/etc/cron\.d|/etc/systemd|/etc/rc\.local|/etc/ssh|/var/spool/cron|/etc/passwd|/etc/shadow|/root/\.ssh)'
is_standard_path() {
    case "$1" in
        /bin/*|/sbin/*|/lib/*|/usr/bin/*|/usr/sbin/*|/usr/lib/*|/usr/libexec/*|/usr/share/*|/opt/*|/var/lib/*|/etc/cron.*) return 0 ;;
        *) return 1 ;;
    esac
}
line_suspicious() {
    local line="$1" p
    grep -qE "$SUS_CMD" <<<"$line" && { echo "match SUS_CMD"; return 0; }
    grep -qE "$SUS_NET" <<<"$line" && { echo "match SUS_NET"; return 0; }
    grep -qE "$SUS_TMP" <<<"$line" && { echo "match SUS_TMP"; return 0; }
    grep -qE "$SUS_DOTFILE" <<<"$line" && { echo "match SUS_DOTFILE"; return 0; }
    grep -qE "$SUS_SENS" <<<"$line" && { echo "match SUS_SENS"; return 0; }
    while IFS= read -r p; do
        [ -n "$p" ] || continue
        is_standard_path "$p" || { echo "nonstd path: $p"; return 0; }
    done < <(grep -oE '(^|[[:space:]])/[A-Za-z0-9._-]+(/[A-Za-z0-9._-]+)+([[:space:]]|$)' <<<"$line" \
             | sed -E 's/^[[:space:]]+//; s/[[:space:]]+$//')
    grep -qE '^[[:space:]]*\*[[:space:]]+\*' <<<"$line" && { echo "match timing"; return 0; }
    grep -qE '^[[:space:]]*\*/[0-9]+[[:space:]]+\*' <<<"$line" && { echo "match timing2"; return 0; }
    return 1
}
